// Sound effects: call ring and ringback, call connected/ended, DM ping, and
// joining/leaving voice. The sounds themselves are generated by
// scripts/generate-sfx.mjs into public/sfx; this file only plays them.
//
// Three browser realities shape it:
//
//  - Autoplay. A page may not make a sound until the person has interacted with
//    it, and a reload (including the one Google sign-in causes) resets that. A
//    one-shot that is refused is simply dropped — a ping that arrives late is
//    worse than none. A LOOP that is refused (an incoming call) is remembered and
//    started on the next click or keypress, because a ringing call you cannot
//    hear is the one failure that matters here.
//  - Bursts. Thirty people joining a voice channel at once must not produce thirty
//    overlapping chimes, so each sound has a minimum gap.
//  - Preference. Sound is per-device, like the theme, and off means off: nothing
//    plays and anything looping stops.
//
// Written so it imports under Node as well (the tests stub `Audio`), which is why
// every browser global is reached through a guard.

const KEY = 'sfx'
const BASE = '/sfx'

export const SOUNDS = [
  'ring', 'ringback', 'call_connected', 'call_ended', 'dm_ping',
  'voice_join', 'voice_leave', 'peer_join', 'peer_leave',
]
const LOOPS = new Set(['ring', 'ringback'])

// Minimum milliseconds between two plays of the same sound. Only the ones that
// can arrive in a flurry need one.
const MIN_GAP_MS = { dm_ping: 500, peer_join: 300, peer_leave: 300 }

const elements = new Map() // name -> HTMLAudioElement, created on first use
const wanted = new Set() // loops that should be sounding right now
const lastPlayed = new Map() // name -> ms
const listeners = new Set()
let unlockBound = false

function readEnabled() {
  try { return globalThis.localStorage?.getItem(KEY) !== 'off' } catch { return true }
}
let enabled = readEnabled()

const element = (name) => {
  let el = elements.get(name)
  if (!el) {
    el = new globalThis.Audio(`${BASE}/${name}.wav`)
    el.preload = 'auto'
    el.loop = LOOPS.has(name)
    elements.set(name, el)
  }
  return el
}

function start(name) {
  const el = element(name)
  try { el.currentTime = 0 } catch { /* not loaded yet: it starts at 0 anyway */ }
  const result = el.play()
  // `play()` rejects when autoplay is blocked (or the file failed to load).
  // Never let that surface: a missing sound must not break a call.
  result?.catch?.(() => {})
}

// Autoplay is lifted by the first real interaction: retry the loops that were
// refused. The listeners stay, because the page can lose and regain the right
// (a reload) and they cost nothing while `wanted` is empty.
function bindUnlock() {
  if (unlockBound || typeof globalThis.addEventListener !== 'function') return
  unlockBound = true
  const retry = () => {
    if (!enabled) return
    for (const name of wanted) {
      const el = elements.get(name)
      if (el?.paused) start(name)
    }
  }
  for (const type of ['pointerdown', 'keydown', 'touchstart']) {
    globalThis.addEventListener(type, retry, { passive: true })
  }
}

export function play(name) {
  if (!SOUNDS.includes(name)) return
  if (typeof globalThis.Audio !== 'function') return
  // Off means off: nothing starts and nothing is remembered, so switching sound
  // back on halfway through a ring does not start that ring late.
  if (!enabled) return
  if (LOOPS.has(name)) {
    wanted.add(name)
    bindUnlock()
  }
  const gap = MIN_GAP_MS[name]
  const now = Date.now()
  if (gap && now - (lastPlayed.get(name) ?? -Infinity) < gap) return
  lastPlayed.set(name, now)
  start(name)
}

export function stop(name) {
  wanted.delete(name)
  const el = elements.get(name)
  if (!el) return
  try { el.pause(); el.currentTime = 0 } catch { /* already stopped */ }
}

export function stopAll() {
  for (const name of [...elements.keys()]) stop(name)
  wanted.clear()
}

export const isEnabled = () => enabled

export function setEnabled(on) {
  enabled = !!on
  try { globalThis.localStorage?.setItem(KEY, enabled ? 'on' : 'off') } catch { /* private mode */ }
  if (!enabled) stopAll()
  listeners.forEach(fn => fn(enabled))
}

export function subscribe(fn) {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

/** For tests only: forget all state so each case starts clean. */
export function _reset() {
  stopAll()
  elements.clear()
  lastPlayed.clear()
  listeners.clear()
  enabled = readEnabled()
}
